const q = $json.query ?? {};
const mode = String(q['hub.mode'] ?? '');
const token = String(q['hub.verify_token'] ?? '');
const challenge = String(q['hub.challenge'] ?? '');

const expected = String($env.META_VERIFY_TOKEN ?? '');

if (mode !== 'subscribe') {
  return [{ json: { ok: false, http_status: 400, reason: 'invalid_mode' } }];
}

if (!expected || token !== expected) {
  return [{ json: { ok: false, http_status: 403, reason: 'invalid_verify_token' } }];
}

return [{ json: { ok: true, http_status: 200, challenge } }];

const headers = $json.headers ?? {};
const body = $json.body ?? {};
const signature = String(
  headers['x-hub-signature-256'] ??
  headers['X-Hub-Signature-256'] ??
  ''
);

return [{
  json: {
    request: {
      headers,
      signature,
      body,
      received_at: new Date().toISOString()
    },
    binary_present: !!$binary?.data
  },
  binary: $binary
}];

/*
Meta signs the raw HTTP body with the App Secret and sends the digest in
X-Hub-Signature-256. This node is the channel port's 'verify' operation: it
runs before normalisation and before any domain, identity or LLM step, and it
fails closed. Nothing downstream ever sees an unverified body.

The algorithm is the one in platform/channels/meta-signature.ts
(verifyMetaSignature), kept equivalent on purpose. The Code-node route needs
NODE_FUNCTION_ALLOW_BUILTIN=crypto, which the compose files under
infrastructure/docker/ set; without it this require throws and the gateway
rejects, which is the correct failure direction.
*/
const crypto = require('crypto');

function verifyMetaSignature(rawBody, header, appSecret) {
  if (!Buffer.isBuffer(rawBody)) return false;
  if (typeof appSecret !== 'string' || appSecret.length === 0) return false;
  if (typeof header !== 'string' || !header.startsWith('sha256=')) return false;
  const provided = Buffer.from(header.slice('sha256='.length), 'utf8');
  const expected = Buffer.from(crypto.createHmac('sha256', appSecret).update(rawBody).digest('hex'), 'utf8');
  return provided.length === expected.length && crypto.timingSafeEqual(provided, expected);
}

const item = $input.first();
const request = item.json.request ?? {};
const headers = request.headers ?? {};
const header = headers['x-hub-signature-256'] ?? headers['X-Hub-Signature-256'];
const base64 = item.binary?.data?.data;
const rawBody = base64 ? Buffer.from(base64, 'base64') : null;
const appSecret = String($env.META_APP_SECRET ?? '');
const allowUnverified = String($env.ALLOW_UNVERIFIED_META_WEBHOOK ?? '').toLowerCase() === 'true';

// Page id and event id only: identifying the event is not normalising it.
const body = request.body ?? {};
const entry = body.entry?.[0] ?? {};
const messaging = entry.messaging?.[0] ?? {};
const pageId = String(messaging.recipient?.id ?? entry.id ?? 'unknown');
const mid = messaging.message?.mid ?? messaging.postback?.mid ?? messaging.reaction?.mid ?? null;

// Page id and reason only. Never the body, never the header value.
function reject(reason) {
  console.log(JSON.stringify({ event: 'meta_webhook_rejected', page_id: pageId, reason }));
  return [{ json: { security: { decision: 'reject', reason }, page_id: pageId } }];
}

const signed = verifyMetaSignature(rawBody, header, appSecret);

if (!signed && !allowUnverified) {
  if (!rawBody) return reject('missing_raw_body');
  if (!appSecret) return reject('missing_app_secret');
  return reject('invalid_meta_signature');
}

if (!signed) {
  // Local development only. scripts/staging/preflight.ts refuses any deployed
  // environment with ALLOW_UNVERIFIED_META_WEBHOOK set.
  console.log(JSON.stringify({ event: 'meta_webhook_unverified_accept', page_id: pageId, reason: 'allow_unverified_development_bypass' }));
}

/*
message_reads, message_deliveries, messaging_optins and some reactions carry
no event id. The request verified; there is simply nothing to deduplicate and
nothing to process, so it is acknowledged 200 and dropped (see the
'Event Has Id?' branch). A 403 here would claim the signature was missing,
which is false, and Meta disables a subscription whose deliveries keep
failing - taking real inbound messages down with it.
*/
if (!mid) {
  console.log(JSON.stringify({ event: 'meta_webhook_no_event_id', page_id: pageId, reason: 'nothing_to_process' }));
}

return [{
  json: {
    security: {
      decision: signed ? 'accept' : 'development_only_accept',
      reason: signed ? 'signature_verified' : 'allow_unverified_development_bypass'
    },
    event: {
      page_id: pageId,
      message_id: mid ? String(mid) : null,
      idempotency_key: mid ? 'meta:' + pageId + ':' + mid : null,
      operation: 'meta_webhook_event',
      request_hash: rawBody ? crypto.createHash('sha256').update(rawBody).digest('hex') : 'unverified'
    },
    request
  },
  binary: item.binary
}];

/*
Meta's signature covers the body only: no timestamp, no nonce, so a captured
valid request replays forever. Replay defence is deduplication of the event id
against durable state, which happens here, before normalisation.

private.reserve_idempotency returns CREATED for the first caller of a key.
Any other status means Meta is retrying a delivery we already hold:
acknowledge 200 so it stops retrying, and drop it.

It raises idempotency_key_conflict when the same key arrives with a different
request hash. The Reserve node continues on error so that arrives here as an
item instead of a 500, and NAD-016 decided to treat it as a duplicate: the
only ways to reach it are a provider-side re-encoding of a delivery already
held and a caller who already has a valid signature over a different body for
the same event id, and both are better dropped than retried forever.

Every OTHER error - outage, timeout, pool exhaustion, an unbound credential,
permission denied - means the reservation did not happen. That must not be
acknowledged: a verified first-time message would be lost permanently because
Meta saw success, and an availability failure would be recorded as a replay.
Those rethrow, so Meta sees a 500 and retries with backoff.

The conflict is read from the item's MESSAGE fields only, and the error object
is read field by field rather than stringified. Two wrong ways to do this,
both tried: reading reserved.error first and stringifying it gives
"[object Object]", because the node's error is an object, and the conflict is
never seen; stringifying the WHOLE item sees far too much, because the node
puts its own definition on the error (including the notes field below, which
names this very string), so an unrelated outage reads as a conflict and the
message is acknowledged and lost. The false-positive surface of a whole-item
scan is whatever n8n decides to attach, not what reserve_idempotency raises.

ponytail: the reservation is never completed or released. A failure after
CREATED leaves the key IN_PROGRESS, so Meta's retry looks like a duplicate and
that delivery is dropped: at-most-once. Upgrade path when the domain side
exists - mark the key COMPLETED once the domain acknowledges, or expire
IN_PROGRESS rows through idempotency_keys.expires_at.
*/
const reserved = $input.first().json ?? {};
const verified = $('Verify Meta Signature').first();
const status = String(reserved.status ?? '');
const conflict = [reserved.message, reserved.error?.message, reserved.error?.description]
  .some((m) => typeof m === 'string' && m.includes('idempotency_key_conflict'));

if (!status && !conflict) {
  throw new Error('reserve_idempotency failed: ' + (reserved.message ?? 'unknown'));
}

const duplicate = conflict || status !== 'CREATED';

if (duplicate) {
  console.log(JSON.stringify({
    event: conflict ? 'meta_webhook_idempotency_conflict' : 'meta_webhook_duplicate',
    page_id: verified.json.event?.page_id,
    reason: conflict ? 'same_event_id_different_body' : 'event_already_reserved:' + status
  }));
}

return [{
  json: { ...verified.json, idempotency: { status, duplicate, conflict } },
  binary: verified.binary
}];

const event = $json.request?.body ?? {};
const entry = event.entry?.[0] ?? {};
const messaging = entry.messaging?.[0] ?? {};
const message = messaging.message ?? {};

const senderId = messaging.sender?.id ?? null;
const recipientId = messaging.recipient?.id ?? entry.id ?? null;
const messageId = message.mid ?? null;
const text = typeof message.text === 'string' ? message.text : '';

const messageType =
  message.text ? 'text' :
  message.attachments ? 'attachment' :
  messaging.postback ? 'postback' :
  messaging.reaction ? 'reaction' :
  'unknown';

if (!senderId || !messageId) {
  return [{
    json: {
      accepted: false,
      reject_reason: 'missing_sender_or_message_id',
      channel: 'facebook_messenger',
      raw_event: event
    }
  }];
}

return [{
  json: {
    accepted: true,
    channel: 'facebook_messenger',
    channel_user_id: String(senderId),
    page_id: String(recipientId),
    message_id: String(messageId),
    conversation_id: `facebook_messenger:${senderId}`,
    text,
    message_type: messageType,
    timestamp: messaging.timestamp ?? Date.now(),
    is_echo: Boolean(message.is_echo),
    postback: messaging.postback ?? null,
    attachments: message.attachments ?? [],
    raw_event: event,
    source_trust: 'untrusted',
    received_at: new Date().toISOString()
  }
}];

const x = $json;
return [{
  json: {
    ...x,
    idempotency_key: `${x.channel}:${x.message_id}`,
    processing: {
      stage: 'INBOUND_NORMALIZED',
      idempotency_required: true,
      language_detection: 'WF-03-or-language-detector',
      security_classification: 'WF-01',
      identity_resolution: 'WF-02',
      state_resolution: 'WF-03',
      intent_resolution: 'WF-04'
    }
  }
}];
